css:
.inputs{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:.75rem;margin-bottom:1rem}
.inputs label{display:block;font-size:.9rem;color:var(--muted);margin-bottom:.25rem}
.inputs input{width:100%;box-sizing:border-box;font:inherit;font-size:1.1rem;padding:.45rem .6rem;border:1.5px solid var(--line);border-radius:.6rem;background:var(--bg);color:var(--ink)}
.inputs input:focus-visible{outline:3px solid var(--focus);outline-offset:1px}
.steps{display:grid;grid-template-columns:auto 1fr;gap:0 .75rem;align-items:center}
.row{display:grid;grid-template-columns:1fr 2rem 1fr;align-items:center;gap:.5rem;padding:.55rem .8rem;border-radius:.7rem;background:var(--card);border:1px solid var(--line);font-size:1.1rem}
.row .amount{text-align:right;color:var(--cat1);font-weight:700}
.row .value{color:var(--cat2);font-weight:700}
.row .arrow{text-align:center;color:var(--muted)}
.row.unit{background:var(--accent-bg);border-color:var(--accent)}
.op{grid-column:2;font-size:.95rem;color:var(--muted);padding:.2rem .8rem}
.op strong{color:var(--accent)}
.side{grid-column:1;font-size:.85rem;color:var(--muted);text-align:right;white-space:nowrap}
.result{margin-top:1rem}

script:
(function(){
const $ = id => document.getElementById(id);
const num = (x, digits) => x.toLocaleString('de-CH', {minimumFractionDigits: digits, maximumFractionDigits: digits});
const kg = x => num(x, Number.isInteger(x) ? 0 : 1) + ' kg';
const fr = x => 'Fr. ' + num(x, 2);
function read(id){ const v = parseFloat($(id).value); return Number.isFinite(v) && v > 0 ? v : null; }
function update(){
  const a = read('knownAmount'), b = read('knownValue'), c = read('wantedAmount');
  if (a === null || b === null || c === null) {
    $('explain').textContent = 'Gib drei Zahlen grösser als 0 ein.';
    return;
  }
  const one = b / a, result = one * c;
  $('r1a').textContent = kg(a); $('r1v').textContent = fr(b);
  $('r2v').textContent = fr(one);
  $('r3a').textContent = kg(c); $('r3v').textContent = fr(result);
  $('op1').replaceChildren('beide Seiten ', Object.assign(document.createElement('strong'), {textContent: ': ' + num(a, Number.isInteger(a) ? 0 : 1)}));
  $('op2').replaceChildren('beide Seiten ', Object.assign(document.createElement('strong'), {textContent: '· ' + num(c, Number.isInteger(c) ? 0 : 1)}));
  const more = c > a ? 'mehr' : (c < a ? 'weniger' : 'gleich viel');
  $('explain').textContent = '1 kg kostet ' + fr(one) + '. ' + kg(c) + ' kosten also ' + fr(result) + (more === 'gleich viel' ? '.' : ': ' + more + ' Ware, ' + (more === 'mehr' ? 'höherer' : 'tieferer') + ' Preis.');
}
['knownAmount', 'knownValue', 'wantedAmount'].forEach(id => $(id).addEventListener('input', update));
update();
})();
